#!/bin/bash
# NB-S002-P008-WP002 — Patch Yoast SEO meta on dev site via REST API
# Run AFTER meta-registration.php is deployed to dev (see deployment notes below).
#
# Prerequisites:
#   1. meta-registration.php must be deployed to dev (run upress_ftps_upload.py first)
#   2. Source the credentials: source /Users/nimrod/Documents/nimrod-bio/.env.upress.dev
#
# Deployment note:
#   python3 scripts/upress_ftps_upload.py \
#     --local-dir nimrod.bio/wp-content/themes/nimrod-bio-2026/inc \
#     --remote-dir wp-content/themes/nimrod-bio-2026/inc \
#     --skip-ip-check
#   (Must be run from IP 147.235.197.125 or after adding current IP to allowlist)

set -euo pipefail

source "$(dirname "$0")/../.env.upress.dev"
BASE="http://nimrod-bio-2026.s887.upress.link"
AUTH="${WP_REST_USER}:${WP_REST_APP_PASSWORD}"

echo "=== Verifying Yoast meta fields are registered on dev ==="
REGISTERED=$(curl -s -k -u "$AUTH" -X OPTIONS "$BASE/wp-json/wp/v2/posts" | python3 -c "
import sys,json
d=json.load(sys.stdin)
meta_props = d.get('schema',{}).get('properties',{}).get('meta',{}).get('properties',{})
yoast = [k for k in meta_props if 'yoast' in k]
print('REGISTERED' if yoast else 'NOT_REGISTERED')
")

if [ "$REGISTERED" != "REGISTERED" ]; then
  echo "ERROR: Yoast meta fields not registered on dev site."
  echo "Deploy meta-registration.php first (see script header)."
  exit 1
fi
echo "OK: Yoast meta fields registered."
echo ""

patch_entity() {
  local post_type="$1"
  local post_id="$2"
  local seo_title="$3"
  local seo_desc="$4"

  RESULT=$(curl -s -k -X POST -u "$AUTH" "$BASE/wp-json/wp/v2/${post_type}/${post_id}" \
    -H "Content-Type: application/json" \
    -d "{\"meta\": {\"_yoast_wpseo_title\": $(python3 -c "import json,sys; print(json.dumps(sys.argv[1]))" "$seo_title"), \"_yoast_wpseo_metadesc\": $(python3 -c "import json,sys; print(json.dumps(sys.argv[1]))" "$seo_desc")}}" \
    | python3 -c "
import sys,json
d=json.load(sys.stdin)
m=d.get('meta',{})
title_ok = bool(m.get('_yoast_wpseo_title',''))
desc_ok = bool(m.get('_yoast_wpseo_metadesc',''))
print(f'ID={d.get(\"id\")} title_set={title_ok} desc_set={desc_ok}')
")
  echo "  $post_type/$post_id: $RESULT"
}

